import { test } from 'node:test';
import assert from 'node:assert/strict';
import { ContaBancaria } from './solution.mjs';

test('depositar soma ao saldo', () => {
  const conta = new ContaBancaria(100);
  conta.depositar(50);
  assert.equal(conta.consultarSaldo(), 150);
});

test('sacar subtrai do saldo', () => {
  const conta = new ContaBancaria(100);
  conta.sacar(30);
  assert.equal(conta.consultarSaldo(), 70);
  conta.sacar(70);
  assert.equal(conta.consultarSaldo(), 0);
});

test('recusa depósito e saque inválidos', () => {
  const conta = new ContaBancaria(100);
  assert.throws(() => conta.depositar(-10));
  assert.throws(() => conta.depositar(0));
  assert.throws(() => conta.sacar('50'));
  assert.throws(() => conta.sacar(999));
});

test('o saldo é privado: não existe campo público', () => {
  const conta = new ContaBancaria(100);
  assert.equal(Object.keys(conta).length, 0);
  assert.equal(conta.saldo, undefined);
});

solutionCode:
// O saldo é o cofre: campo privado #saldo, só a classe acessa.
export class ContaBancaria {
  #saldo; // campo privado — invisível e intocável de fora

  constructor(saldoInicial) {
    if (typeof saldoInicial !== 'number') {
      throw new Error('saldoInicial precisa ser um número');
    }
    this.#saldo = saldoInicial;
  }

  // Guichê de entrada: valida e só então abre o cofre.
  depositar(valor) {
    if (typeof valor !== 'number' || valor <= 0) {
      throw new Error('depósito precisa ser um número positivo');
    }
    this.#saldo += valor;
  }

  // Guichê de saída: valida e confere se o saldo cobre o valor.
  sacar(valor) {
    if (typeof valor !== 'number' || valor <= 0) {
      throw new Error('saque precisa ser um número positivo');
    }
    if (valor > this.#saldo) {
      throw new Error('saldo insuficiente');
    }
    this.#saldo -= valor;
  }

  // Leitura controlada: só lê, nunca altera.
  consultarSaldo() {
    return this.#saldo;
  }
}
